    if (toggleBtn) {
      new MutationObserver(updateMfdVisibility_ab450)
        .observe(toggleBtn, { attributes: true, attributeFilter: ['aria-pressed'] });
    }
    const subject = document.querySelector('.mfdInfoIcon-ab450');
        if (subject) {
            subject.style.cursor = 'pointer';
            const tooltip = document.createElement('div');
            tooltip.style.display = 'none';
            tooltip.style.position = 'fixed';
            tooltip.style.fontFamily = 'roboto-regular';
            tooltip.style.fontSize = '14px';
            tooltip.style.fontWeight = '400';
            tooltip.style.lineHeight = '1.3em';
            tooltip.style.backgroundColor = 'rgb(254, 254, 254)';
            tooltip.style.color = 'rgb(16, 38, 65)';
            tooltip.style.padding = '12px';
            tooltip.style.width = '300px';
            tooltip.style.borderRadius = '4px';
            tooltip.style.boxShadow = 'rgba(0, 0, 0, 0.15) 0px 2px 10px 0px';
            tooltip.style.opacity = '1';
            tooltip.style.transform = 'none';
            tooltip.style.transition = 'opacity 200ms cubic-bezier(0.4, 0, 0.2, 1), transform 133ms cubic-bezier(0.4, 0, 0.2, 1)';
            tooltip.innerText = 'Start your DIRECTV service with 150+ free live channels and an On Demand library';
            tooltip.id = 'tooltip_ab450';
            tooltip.style.zIndex = '9999';
            document.body.appendChild(tooltip);

            function positionTooltip() {
                var rect = subject.getBoundingClientRect();
                tooltip.style.display = 'block';
                var tooltipH = tooltip.offsetHeight;
                if (rect.top >= tooltipH + 8) {
                    tooltip.style.top = (rect.top - tooltipH - 8) + 'px';
                } else {
                    tooltip.style.top = rect.bottom + 'px';
                }
                var tooltipW = tooltip.offsetWidth;
                var left = rect.left + (rect.width / 2) - (tooltipW / 2);
                if (left + tooltipW > window.innerWidth) {
                    left = window.innerWidth - tooltipW - 8;
                }
                tooltip.style.left = Math.max(8, left) + 'px';
            }

            function showTooltip() {
                positionTooltip();
            }

            function hideTooltip() {
                tooltip.style.display = 'none';
            }

            subject.addEventListener('mouseover', showTooltip);
            subject.addEventListener('mouseout', hideTooltip);
            subject.addEventListener('focus', positionTooltip);
            subject.addEventListener('blur', hideTooltip);

            tooltip.addEventListener('mouseover', function() {
                tooltip.style.display = 'block';
            });
            tooltip.addEventListener('mouseout', hideTooltip);
            window.addEventListener('scroll', hideTooltip, true);
        }
